import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600);

        if (taskInput == null || jobInput == null || outputPath == null) {
            throw new IllegalArgumentException("Required parameters: --task_input, --job_input, --output");
        }

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<TaskEvent> tasks = env.addSource(
                taskSourceOrTest(new GzipTaskEventSource(taskInput)),
                "task-events"
        );

        DataStream<JobEvent> jobs = env.addSource(
                jobSourceOrTest(new GzipJobEventSource(jobInput)),
                "job-events"
        );

        SingleOutputStreamOperator<StageCount> stageCounts = tasks
                .filter(e -> e.getEventType() == TaskEvent.EVENT_SUBMIT)
                .keyBy(TaskEvent::getJobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .aggregate(new CountAgg(), new ToStageCount());

        DataStream<Long> finishedJobIds = jobs
                .filter(e -> e.getEventType() == JobEvent.EVENT_FINISH)
                .map(JobEvent::getJobId)
                .name("finished-job-ids");

        KeyedStream<StageCount, Long> keyedStages = stageCounts.keyBy(sc -> sc.jobId);
        KeyedStream<Long, Long> keyedFinished = finishedJobIds.keyBy(id -> id);

        SingleOutputStreamOperator<Tuple2<Long, Long>> longestStagePerFinishedJob = keyedStages
                .connect(keyedFinished)
                .process(new LongestStageAfterFinish())
                .name("longest-stage-after-finish");

        DataStream<String> formatted = longestStagePerFinishedJob
                .map(t -> "(" + t.f0 + "," + t.f1 + ")")
                .name("format-output");

        formatted
                .addSink(sinkOrTest(new LocalTextFileSink(outputPath)))
                .setParallelism(1)
                .name("write-output");

        env.execute("LongestSessionPerJob");
    }

    private static final class StageCount {
        private final long jobId;
        private final long count;

        private StageCount(long jobId, long count) {
            this.jobId = jobId;
            this.count = count;
        }
    }

    private static final class CountAgg implements AggregateFunction<TaskEvent, Long, Long> {
        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(TaskEvent value, Long accumulator) {
            return accumulator + 1L;
        }

        @Override
        public Long getResult(Long accumulator) {
            return accumulator;
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

    private static final class ToStageCount extends ProcessWindowFunction<Long, StageCount, Long, TimeWindow> {
        @Override
        public void process(Long key, Context context, Iterable<Long> elements, Collector<StageCount> out) {
            long c = elements.iterator().next();
            out.collect(new StageCount(key, c));
        }
    }

    private static final class LongestStageAfterFinish
            extends KeyedCoProcessFunction<Long, StageCount, Long, Tuple2<Long, Long>> {

        private transient ValueState<Long> maxStageCount;
        private transient ValueState<Boolean> finished;
        private transient ValueState<Boolean> timerRegistered;

        @Override
        public void open(org.apache.flink.configuration.Configuration parameters) {
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Long.class));
            finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
            timerRegistered = getRuntimeContext().getState(new ValueStateDescriptor<>("timerRegistered", Boolean.class));
        }

        @Override
        public void processElement1(StageCount value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Long current = maxStageCount.value();
            if (current == null || value.count > current) {
                maxStageCount.update(value.count);
            }
            registerEndTimerIfNeeded(ctx);
        }

        @Override
        public void processElement2(Long value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            finished.update(true);
            registerEndTimerIfNeeded(ctx);
        }

        private void registerEndTimerIfNeeded(Context ctx) throws Exception {
            Boolean isRegistered = timerRegistered.value();
            if (isRegistered == null || !isRegistered) {
                ctx.timerService().registerEventTimeTimer(Long.MAX_VALUE);
                timerRegistered.update(true);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Boolean isFinished = finished.value();
            if (isFinished != null && isFinished) {
                Long max = maxStageCount.value();
                out.collect(Tuple2.of(ctx.getCurrentKey(), max == null ? 0L : max));
            }
            maxStageCount.clear();
            finished.clear();
            timerRegistered.clear();
        }
    }

    private static final class GzipTaskEventSource implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        private GzipTaskEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            long maxTs = Long.MIN_VALUE;
            try (InputStream fis = new FileInputStream(path);
                 InputStream is = path.endsWith(".gz") ? new GZIPInputStream(fis) : fis;
                 BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {

                String line;
                while (running && (line = br.readLine()) != null) {
                    TaskEvent e = TaskEvent.fromCsv(line);
                    if (e == null) {
                        continue;
                    }
                    long ts = e.getTimestampMs();
                    if (ts > maxTs) {
                        maxTs = ts;
                    }

                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collectWithTimestamp(e, ts);
                        if (maxTs != Long.MIN_VALUE) {
                            ctx.emitWatermark(new Watermark(maxTs - 1L));
                        }
                    }
                }
            }

            synchronized (ctx.getCheckpointLock()) {
                ctx.emitWatermark(Watermark.MAX_WATERMARK);
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static final class GzipJobEventSource implements SourceFunction<JobEvent> {
        private final String path;
        private volatile boolean running = true;

        private GzipJobEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            long maxTs = Long.MIN_VALUE;
            try (InputStream fis = new FileInputStream(path);
                 InputStream is = path.endsWith(".gz") ? new GZIPInputStream(fis) : fis;
                 BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {

                String line;
                while (running && (line = br.readLine()) != null) {
                    JobEvent e = JobEvent.fromCsv(line);
                    if (e == null) {
                        continue;
                    }
                    long ts = e.getTimestampMs();
                    if (ts > maxTs) {
                        maxTs = ts;
                    }

                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collectWithTimestamp(e, ts);
                        if (maxTs != Long.MIN_VALUE) {
                            ctx.emitWatermark(new Watermark(maxTs - 1L));
                        }
                    }
                }
            }

            synchronized (ctx.getCheckpointLock()) {
                ctx.emitWatermark(Watermark.MAX_WATERMARK);
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static final class LocalTextFileSink extends RichSinkFunction<String> {

        private final String outputPath;
        private transient BufferedWriter writer;

        private LocalTextFileSink(String outputPath) {
            this.outputPath = outputPath;
        }

        @Override
        public void open(org.apache.flink.configuration.Configuration parameters) throws Exception {
            Path p = Paths.get(outputPath);
            Path parent = p.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            writer = Files.newBufferedWriter(
                    p,
                    StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING,
                    StandardOpenOption.WRITE
            );
        }

        @Override
        public void invoke(String value, Context context) throws Exception {
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.flush();
                writer.close();
            }
        }
    }
}
