import java.io.Serializable;

public class TaskEvent implements Serializable {

    public static final int EVENT_SUBMIT = 0;

    private long timestampMicros;
    private long jobId;
    private int taskIndex;
    private long machineId;
    private int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestampMicros, long jobId, int taskIndex, long machineId, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
    }

    public long getTimestampMicros() {
        return timestampMicros;
    }

    public long getTimestampMs() {
        return timestampMicros / 1000L;
    }

    public long getJobId() {
        return jobId;
    }

    public int getTaskIndex() {
        return taskIndex;
    }

    public long getMachineId() {
        return machineId;
    }

    public int getEventType() {
        return eventType;
    }

    public static TaskEvent fromCsv(String line) {
        if (line == null) {
            return null;
        }
        String trimmed = line.trim();
        if (trimmed.isEmpty()) {
            return null;
        }

        String[] f = trimmed.split(",", -1);
        if (f.length < 6) {
            return null;
        }

        long tsMicros = parseLongOrMinus1(f[0]);
        long jobId = parseLongOrMinus1(f[2]);
        int taskIndex = parseIntOrMinus1(f[3]);
        long machineId = parseLongOrMinus1(f[4]);
        int eventType = parseIntOrMinus1(f[5]);

        if (tsMicros < 0 || jobId < 0 || eventType < 0) {
            return null;
        }

        return new TaskEvent(tsMicros, jobId, taskIndex, machineId, eventType);
    }

    private static long parseLongOrMinus1(String s) {
        if (s == null) {
            return -1L;
        }
        String t = s.trim();
        if (t.isEmpty()) {
            return -1L;
        }
        try {
            return Long.parseLong(t);
        } catch (NumberFormatException e) {
            return -1L;
        }
    }

    private static int parseIntOrMinus1(String s) {
        if (s == null) {
            return -1;
        }
        String t = s.trim();
        if (t.isEmpty()) {
            return -1;
        }
        try {
            return Integer.parseInt(t);
        } catch (NumberFormatException e) {
            return -1;
        }
    }
}
